                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.clicks_itemid AS WITH GA_DATA AS ( SELECT TO_DATE(DATE,\'YYYYMMDD\') AS GA_DATE, CASE WHEN LENGTH(ITEMID) > 14 THEN REPLACE(SPLIT(itemid, \'_\')[2],\'\"\',\'\') ELSE itemid END AS itemid, \'Web\' AS type, sum(itemsViewed) AS CLICKS FROM snitch_db.maplemonk.ga4_web_jan24_clicks_impressions_by_itemid WHERE GA_DATE > \'2024-02-27\' group by 1,2 UNION SELECT TO_DATE(DATE,\'YYYYMMDD\') AS GA_DATE, CASE WHEN LENGTH(ITEMID) > 14 THEN REPLACE(SPLIT(itemid, \'_\')[2],\'\"\',\'\') ELSE itemid END AS itemid, \'App\' AS type, sum(itemsViewed) AS CLICKS FROM snitch_db.maplemonk.ga4_APP_clicks_impressions_by_itemid where ga_date >= \'2024-03-01\' group by 1,2 UNION SELECT TO_DATE(DATE,\'YYYYMMDD\') AS GA_DATE, CASE WHEN LENGTH(ITEMID) > 14 THEN REPLACE(SPLIT(itemid, \'_\')[2],\'\"\',\'\') ELSE itemid END AS itemid, \'Snitch_IOS\' AS type, ifnull(sum(itemsViewed),0) AS CLICKS from snitch_db.maplemonk.operating_system_app2_clicks_itemid where operatingsystem = \'iOS\' group by 1,2 union SELECT TO_DATE(DATE,\'YYYYMMDD\') AS GA_DATE, CASE WHEN LENGTH(ITEMID) > 14 THEN REPLACE(SPLIT(itemid, \'_\')[2],\'\"\',\'\') ELSE itemid END AS itemid, \'Snitch_Android\' AS type, ifnull(sum(itemsViewed),0) AS CLICKS from snitch_db.maplemonk.operating_system_app2_clicks_itemid where operatingsystem = \'Android\' group by 1,2 union SELECT TO_DATE(DATE,\'YYYYMMDD\') AS GA_DATE, CASE WHEN LENGTH(ITEMID) > 14 THEN REPLACE(SPLIT(itemid, \'_\')[2],\'\"\',\'\') ELSE itemid END AS itemid, \'Web2\' AS type, ifnull(sum(itemsViewed),0) AS CLICKS from snitch_db.maplemonk.orders_by_source group by 1,2 ), sku_group as ( select id, upper(trim(sku_group)) as sku_group, sku_class, live_date, status, price from snitch_db.maplemonk.availability_master_v2 ), main_data as ( select a.*,b.sku_group, b.sku_class, b.live_date, b.status, b.price, c.category as category, from ga_data a left join sku_group b on cast(a.itemid as varchar) = cast(b.id as varchar) left join snitch_db.maplemonk.metafields_data c on b.sku_group = c.sku_group where ga_date >= \'2024-06-01\' and itemid not in (\'(other)\',\'(not set)\') and b.sku_group is not null ), sales_data as ( select CASE when webshopney = \'Web\' then \'Web\' WHEN webshopney in (\'Shopney\',\'Appbrew\') then \'App\' when webshopney = \'Snitch_IOS\' and tags like \'%Snitch_IOS%\' then \'Snitch_IOS\' when webshopney = \'Snitch_IOS\' and tags like \'%Snitch_Android%\' then \'Snitch_Android\' when lower(tags) like \'%snitch_web%\' then \'Web2\' ELSE webshopney end as type, order_timestamp::date as date, sku_group, sum(quantity) as total_quantity from snitch_db.maplemonk.fact_items_snitch where lower(ifnull(discount_code,\'n\')) not like \'%eco%\' and lower(ifnull(discount_code,\'n\')) not like \'%influ%\' and order_name not in (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') and tags not in (\'FLITS_LOGICERP\') and order_timestamp::date >= \'2024-06-01\' group by 1,2,3 ) select a.*, coalesce(ifnull(sales.total_quantity,0),0) as total_quantity, case when datediff(day,a.live_date,current_date) <= 30 then \'New\' else a.sku_class end as class, a.CLICKS / NULLIF(SUM(a.CLICKS) OVER (PARTITION BY a.ga_date, a.type), 0) AS clicks_share, SUM(a.CLICKS) OVER (PARTITION BY a.ga_date, a.type ORDER BY a.CLICKS DESC) / NULLIF(SUM(a.CLICKS) OVER (PARTITION BY a.ga_date, a.type), 0) AS cumulative_clicks_share from main_data a left join sales_data sales on a.ga_date = sales.date and a.type = sales.type and a.sku_group = sales.sku_group ;",
                    "transaction": true
                }
            ) }}
